const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const money=n=>'₦'+Math.round(n).toLocaleString('en-NG');
const brand='<a class="brand" href="#"><span class="mark">≈</span>sea<span><em>credit</em></span></a>';
let amount=150000,months=3;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',4000)}
function landing(){app.innerHTML=`<div class="wrap"><header>${brand}<nav><a href="#solutions">Our solutions</a><a href="#how">How it works</a><a href="#about">About us</a><a href="#portal">Client login ↗</a><button class="btn" data-action="apply">Get started <span>↗</span></button></nav></header><main><div class="hero"><div><div class="eyebrow">A little support. A bigger tomorrow.</div><h1>Life moves fast.<br>Let’s move<br><em>forward, together.</em></h1><p>From everyday needs to your next big step. Discover credit designed to bridge the gap between today and payday.</p><div class="actions"><button class="btn" data-action="apply">Explore your options <span class="arrow">↗</span></button><a class="btn light" href="#how">How it works</a></div><div class="small">For salaried professionals in Nigeria.</div></div><div class="hero-art" role="img" aria-label="A professional looking ahead with confidence"><div class="float"><span class="check">✓</span><div><b>A little breathing room.</b><small>For the things that matter.</small></div></div><div class="mini-card"><small>YOUR NEXT CHAPTER</small><strong>Within reach.</strong><div class="mini-bar"></div><p class="small" style="color:#d6e4ff;margin-bottom:0">Small steps. Meaningful progress.</p></div><div class="art-label">YOUR AMBITIONS. OUR INSPIRATION.</div></div></div><div class="strip"><span><b>↗</b> Built around working lives</span><span><b>◎</b> A clearer borrowing journey</span><span><b>▤</b> Your account, in one place</span><span><b>♡</b> Human at heart</span></div><section id="solutions"><div class="section-head"><div><div class="eyebrow">Room to move forward</div><h2>Support for your<br>in-between moments.</h2></div><p>Explore short-term credit options that fit the rhythm of a working life.</p></div><div class="products"><article class="product"><div class="icon">↗</div><h3>Salary advance</h3><p>When an everyday expense arrives before payday, explore a little financial breathing room.</p><button class="textbtn" data-action="apply">Explore salary advance &nbsp; ↗</button></article><article class="product"><div class="icon">◷</div><h3>Short-term personal credit</h3><p>Plan for a pressing need with a clear view of your repayment amount, dates, and obligations.</p><button class="textbtn" data-action="apply">Explore personal credit &nbsp; ↗</button></article></div></section><div class="calculator" id="calculator"><div><div class="eyebrow">Plan before you borrow</div><h2>A clearer picture.<br>A more confident decision.</h2><p>Explore how a loan amount and repayment period could affect your monthly payment.</p><p class="small">Illustrative calculator only. Uses a sample flat interest rate of 3% per month with no additional fees. This is not a Sea Credit offer or confirmed product range. Actual eligibility, rates, fees, and terms require confirmation.</p></div><div class="calcbox"><label for="amount">How much would you like to explore?</label><div class="amount" id="amount-value"></div><input id="amount" type="range" min="50000" max="1000000" step="25000" value="150000"><div class="small" style="display:flex;justify-content:space-between"><span>₦50,000</span><span>₦1,000,000</span></div><label style="margin-top:25px">Illustrative repayment period</label><div class="terms">${[1,3,6].map(n=>`<button data-month="${n}" class="${n===months?'active':''}">${n} month${n>1?'s':''}</button>`).join('')}</div><div class="calc-result"><span class="small">Estimated monthly payment</span><strong id="monthly"></strong></div><p class="small" id="total"></p><button class="btn" style="width:100%" data-action="apply">Take the next step ↗</button></div></div><section id="how"><div class="eyebrow">Your journey, made simpler</div><h2>Three steps to your next step.</h2><div class="steps"><article><div class="step-no">01 / EXPLORE</div><h3>Tell us what you need</h3><p>Choose a borrowing amount and share the information needed to understand your circumstances.</p></article><article><div class="step-no">02 / REVIEW</div><h3>Understand your options</h3><p>Review your eligibility, repayment schedule, and all costs before making a commitment.</p></article><article><div class="step-no">03 / MANAGE</div><h3>Stay in control</h3><p>Keep track of your balance, repayments, and documents from your client account.</p></article></div></section><section id="about" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">Meet Sea Credit</div><h2>Built for people<br>moving forward.</h2></div><p>Sea Credit Ltd is developing microcredit solutions for Nigerian employees, with a focus on salary advances and short-term lending. Our vision starts with access to credit that helps bridge everyday financial gaps.</p></div></section><section class="faq" style="padding-top:0"><h2>A few things you might be wondering.</h2>${[['Who is Sea Credit designed for?','Sea Credit’s focus is on salaried professionals in Nigeria. Final eligibility criteria will be confirmed as part of the application process.'],['What will my loan cost?','Your loan offer must set out the interest rate, fees, total repayment, and due dates before acceptance. The calculator above uses sample terms and is not a quotation.'],['Can I manage my loan online?','Create a test account, submit an application, and track its review status in your client portal. Repayments and document uploads are planned for a later milestone.'],['Is this site accepting real applications?','This development version saves test accounts and applications for manual review. Use fictional information only. No real lending offer, disbursement, or payment is made.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><div class="cta"><div><div class="eyebrow">Your next chapter</div><h2>Let’s take the next step, together.</h2></div><button class="btn" data-action="apply">Explore your options ↗</button></div></main><footer><div class="foot">${brand}<span class="small">Empowering dreams, one loan at a time.</span><a class="small" href="https://www.linkedin.com/company/sea-credit-ltd/" target="_blank" rel="noopener">Connect on LinkedIn ↗</a></div><div class="legal">© ${new Date().getFullYear()} Sea Credit Ltd. &nbsp; • &nbsp; Development environment · Test accounts only.<br>Illustrative product terms. Applications are saved for testing; no lending offer or payment processing is provided.</div></footer></div>`;updateCalc()}
function updateCalc(){document.querySelector('#amount-value').textContent=money(amount);document.querySelector('#amount').value=amount;document.querySelector('#monthly').textContent=money(amount*(1+.03*months)/months);document.querySelector('#total').textContent=`Total repayment: ${money(amount*(1+.03*months))} · Sample interest: ${money(amount*.03*months)}`}
